'recibo-simple':()=>documentBuilder('recibo',[['from','Recibido de','text','Cliente Ejemplo'],['to','Recibido por','text','Mi negocio'],['concept','Concepto de pago','text','Servicio realizado'],['amount','Importe','number',250],['date','Fecha','date',today()]],v=>{const amount=nonnegative(v.amount,'Importe');return `RECIBO PARTICULAR · SIN VALOR FISCAL\n\nFecha: ${v.date}\nRecibido de: ${v.from}\nRecibido por: ${v.to}\n\nConcepto: ${v.concept}\nImporte: Q ${fmt(amount)}\n\n_____________________________\nFirma de quien recibe\n\nNo es una factura FEL ni comprobante tributario.`}),
'factura-proforma':()=>documentBuilder('proforma',[['seller','Emisor','text','Mi negocio'],['customer','Cliente','text','Cliente Ejemplo'],['item','Artículo o servicio','text','Diseño gráfico'],['units','Cantidad','number',2],['price','Precio unitario (Q)','number',125],['date','Fecha','date',today()]],v=>{const u=positive(v.units,'Unidades'),p=nonnegative(v.price,'Precio');return `COTIZACIÓN / FACTURA PROFORMA\nDOCUMENTO SIN VALOR FISCAL\n\nFecha: ${v.date}\nEmisor: ${v.seller}\nCliente: ${v.customer}\n\nDescripción\n${v.item}\nCantidad: ${fmt(u)}\nPrecio unitario: Q ${fmt(p)}\n\nTOTAL ESTIMADO: Q ${fmt(u*p)}\n\nDocumento informativo: NO es una factura FEL ni comprobante tributario oficial.`}),
