const imageTool=(mode)=>{app.innerHTML=`<div class="app-form"><label class="field">Selecciona una imagen<input type="file" id="imageFile" accept="image/*"></label><div id="imageOptions"></div><div class="app-actions"><button class="btn" id="processImage" type="button">Procesar imagen ↗</button></div><div id="output" aria-live="polite"></div></div>`;let bitmap=null,originalSize=0;$('#imageFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){show(result('Archivo demasiado grande','Utiliza una imagen menor a 20 MB.'));return}try{if(bitmap?.close)bitmap.close();bitmap=await createImageBitmap(file);originalSize=file.size;const opts=$('#imageOptions');opts.innerHTML=mode==='compress'?`<div class="field-grid">${field('quality','Calidad (10 a 100)','number',75)}${field('format','Formato','select','',{options:[['image/webp','WebP'],['image/jpeg','JPG']]})}</div>`:mode==='resize'?`<div class="field-grid">${field('w','Ancho (px)','number',bitmap.width)}${field('h','Alto (px)','number',bitmap.height)}</div>`:`<div class="field-grid">${field('tolerance','Tolerancia de color (0 a 180)','number',45)}${field('softness','Suavidad del borde (0 a 80)','number',20)}</div><p class="app-hint">Se usa como referencia el color del píxel de la esquina superior izquierda. No es segmentación de IA.</p>`;show(result(bitmap.width+' × '+bitmap.height+' px','Archivo: '+fmt(file.size/1024)+' KB'))}catch(err){show(result('No se pudo abrir','Prueba PNG, JPEG o WebP.'))}});onClick('#processImage',()=>{try{if(!bitmap)throw Error('Selecciona primero una imagen.');let w=bitmap.width,h=bitmap.height;if(mode==='resize'){w=positive($('#w').value,'Ancho');h=positive($('#h').value,'Alto');if(!Number.isInteger(w)||!Number.isInteger(h)||w>8000||h>8000)throw Error('Dimensiones enteras de 1 a 8,000 píxeles.')}if(w*h>22000000)throw Error('Imagen demasiado grande para procesarla en este dispositivo.');const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:mode==='remove'});ctx.drawImage(bitmap,0,0,w,h);if(mode==='remove'){const tol=nonnegative($('#tolerance').value,'Tolerancia'),soft=nonnegative($('#softness').value,'Suavidad');if(tol>180||soft>80)throw Error('Ajusta tolerancia y suavidad dentro de los límites indicados.');const id=ctx.getImageData(0,0,w,h),d=id.data;const [r,g,b]=d;for(let i=0;i<d.length;i+=4){const dist=Math.sqrt((d[i]-r)**2+(d[i+1]-g)**2+(d[i+2]-b)**2);const alpha=soft===0?(dist>tol?1:0):Math.min(1,Math.max(0,(dist-tol)/soft));d[i+3]=Math.round(d[i+3]*alpha)}ctx.putImageData(id,0,0)}const mime=mode==='compress'?$('#format').value:'image/png';let quality=mode==='compress'?Number($('#quality').value)/100:1;if(quality<=0||quality>1)throw Error('La calidad debe estar entre 10 y 100.');c.toBlob(blob=>{if(!blob){show(result('No se pudo procesar','Prueba otro formato.'));return}const url=URL.createObjectURL(blob);show(`<div class="app-result"><strong>${fmt(blob.size/1024)} KB</strong><p>Original: ${fmt(originalSize/1024)} KB · Resultado: ${w} × ${h} px</p></div><img class="image-preview" alt="Vista previa del resultado" src="${url}"><div class="app-actions"><a class="btn" download="vyntools-imagen.${mime==='image/jpeg'?'jpg':mime==='image/webp'?'webp':'png'}" href="${url}">Descargar imagen ↓</a></div>`);},mime,quality)}catch(err){show(`<div class="app-result app-error">${esc(err.message)}</div>`)}})};
Object.assign(tool,{'comprimir-imagen':()=>imageTool('compress'),'redimensionar-imagen':()=>imageTool('resize'),'quitar-fondo-simple':()=>imageTool('remove'),
'crear-qr':()=>{app.innerHTML='<label class="field">Texto o enlace<textarea id="qrText" rows="4" maxlength="1200" placeholder="https://vyntools.com/">https://vyntools.com/</textarea></label><div class="app-actions" style="margin:15px 0"><button class="btn" id="create">Generar QR</button><button class="btn secondary" id="downloadQR" disabled>Descargar PNG ↓</button></div><div id="qrBox" style="display:flex;justify-content:center;padding:15px"></div><div id="output"></div>';const load=()=>new Promise((resolve,reject)=>{if(window.QRCode)return resolve();const tag=document.createElement('script');tag.src='https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';tag.onload=resolve;tag.onerror=()=>reject(Error('No se pudo cargar la biblioteca de QR. Revisa la conexión a Internet.'));document.head.appendChild(tag)});onClick('#create',async()=>{try{const t=$('#qrText').value.trim();if(!t)throw Error('Escribe un texto o enlace.');if(t.length>1200)throw Error('Utiliza un contenido más corto.');await load();$('#qrBox').innerHTML='';new window.QRCode($('#qrBox'),{text:t,width:240,height:240,colorDark:'#0d2530',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M});$('#downloadQR').disabled=false;show('<p class="app-hint">Código generado. Prueba la lectura antes de imprimirlo.</p>')}catch(e){show(`<div class="app-result app-error">${esc(e.message)}</div>`)}});onClick('#downloadQR',()=>{const canvas=$('#qrBox canvas');const image=$('#qrBox img');const src=canvas?.toDataURL('image/png')||image?.src;if(src){const a=document.createElement('a');a.href=src;a.download='vyntools-qr.png';a.click()}});},
});
