const quiz=(id)=>{const cfg=questionnaires[id];let index=0,scores=Array(cfg.labels.length).fill(0),selected=null;function draw(){if(index>=cfg.questions.length){const top=Math.max(...scores),winner=scores.indexOf(top);app.innerHTML=`<div class="app-result"><p class="app-hint">RESULTADO RECREATIVO</p><strong>${esc(cfg.labels[winner])}</strong><p>${esc(cfg.description[winner])}</p><small>Este resultado es un juego de reflexión; no equivale a una evaluación profesional o diagnóstico.</small></div><div class="app-actions" style="margin-top:12px"><button class="btn" id="again">Volver a empezar</button></div>`;onClick('#again',()=>{index=0;scores.fill(0);draw()});return}const [q,options]=cfg.questions[index];app.innerHTML=`<div class="progress-track"><div class="progress-fill" style="width:${index/cfg.questions.length*100}%"></div></div><p class="app-hint">Pregunta ${index+1} de ${cfg.questions.length}</p><h3 class="quiz-title">${esc(q)}</h3><div class="choices">${options.map((s,i)=>`<button type="button" class="quiz-choice" data-choice="${i}">${esc(s)}</button>`).join('')}</div><p class="app-hint">Selecciona la respuesta que más se acerque a tu preferencia.</p>`;$$('[data-choice]').forEach(b=>b.addEventListener('click',()=>{scores[Number(b.dataset.choice)]++;index++;draw()}))}draw()};
Object.keys(questionnaires).forEach(id=>tool[id]=()=>quiz(id));
