'horoscopo':()=>{const signs=['Aries','Tauro','Géminis','Cáncer','Leo','Virgo','Libra','Escorpio','Sagitario','Capricornio','Acuario','Piscis'];const lines=['Un proyecto pequeño puede sorprenderte si hoy das el primer paso.','Una conversación amable puede abrir una perspectiva interesante.','Reserva un momento para hacer algo que disfrutas sin prisas.','Mira lo cotidiano desde un ángulo nuevo y descubre una oportunidad creativa.','Una pausa consciente te ayudará a ordenar tus ideas.','Hoy puedes practicar paciencia y celebrar un avance pequeño.','Prueba aprender algo que has tenido pendiente.','Compartir una buena idea puede conectar a personas distintas.'];app.innerHTML=field('sign','Signo zodiacal','select','',{options:signs.map(x=>[x,x])})+'<div class="app-actions" style="margin-top:14px"><button class="btn" id="read">Ver lectura recreativa ↗</button></div><div id="output"></div>';onClick('#read',()=>{const s=$('#sign').value,seed=[...s+today()].reduce((a,c)=>a+c.charCodeAt(0),0);show(result(s+' · '+new Date().toLocaleDateString('es-GT'),lines[seed%lines.length],'Contenido ficticio para entretenimiento, no predice acontecimientos.'))});},
'nombres-bebe':()=>{const all=[['Alma','f','Breve, cálido y clásico'],['Lucía','f','Nombre latino muy extendido'],['Valentina','f','Sonoro y romántico'],['Sofía','f','Tradicional y elegante'],['Emma','f','Corto e internacional'],['Clara','f','Limpio y clásico'],['Elena','f','Clásico y elegante'],['Luna','f','Evoca el cielo nocturno'],['Camila','f','Suave y familiar'],['Mía','f','Corto y sencillo'],['Noa','u','Breve y moderno'],['Alex','u','Versátil'],['Ariel','u','Tradicional en distintas culturas'],['Sasha','u','Internacional'],['Leo','m','Breve y reconocible'],['Mateo','m','Tradicional y popular'],['Daniel','m','Clásico'],['Gabriel','m','Sonoro y elegante'],['Lucas','m','Fácil de recordar'],['Sebastián','m','Largo y tradicional'],['Emilio','m','Clásico'],['Nicolás','m','Muy conocido'],['Samuel','m','Tradicional'],['Adrián','m','Moderno y tradicional'],['Gael','m','Corto y actual'],['Iris','f','Evoca una flor'],['Olivia','f','Internacional'],['Isabel','f','Clásico'],['Aitana','f','De uso contemporáneo'],['Dalia','f','Evoca una flor']];let favorites=[];try{favorites=JSON.parse(localStorage.getItem('vyntools:baby-favorites:v1')||'[]');if(!Array.isArray(favorites))favorites=[]}catch{favorites=[]}app.innerHTML=`<div class="field-grid">${field('gender','Preferencia','select','',{options:[['all','Todos'],['f','Femeninos'],['m','Masculinos'],['u','Unisex']]})}${field('initial','Inicial','text','',{placeholder:'Ej. M (opcional)'})}</div><div class="app-actions" style="margin:14px 0"><button class="btn" id="searchNames">Buscar nombres</button><button class="btn secondary" id="copyFav">Copiar favoritos</button></div><div id="output"></div>`;function render(){const gender=$('#gender').value,initial=$('#initial').value.trim().toLocaleLowerCase('es');const list=all.filter(x=>(gender==='all'||x[1]===gender)&&(initial===''||x[0].toLocaleLowerCase('es').startsWith(initial)));show(`<p class="app-hint">${list.length} nombres encontrados. Toca ☆ para guardar favoritos.</p><div class="choices">${list.map(x=>`<button class="quiz-choice" type="button" data-baby="${esc(x[0])}">${favorites.includes(x[0])?'★':'☆'} ${esc(x[0])} — ${esc(x[2])}</button>`).join('')||'<p>No hay coincidencias.</p>'}</div><p class="app-hint">Favoritos: ${esc(favorites.join(', ')||'Ninguno')}</p>`);$$('[data-baby]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.baby;favorites=favorites.includes(s)?favorites.filter(x=>x!==s):[...favorites,s];try{localStorage.setItem('vyntools:baby-favorites:v1',JSON.stringify(favorites))}catch{}render()}))}onClick('#searchNames',render);onClick('#copyFav',()=>favorites.length?copy(favorites.join(', ')):alert('Selecciona al menos un nombre.'));render()},
